    {"id":"zy","symbol":"coefficient of y in Z","value":3,"provenance":"given"},
    {"id":"xb","symbol":"lower bound on x","value":1,"provenance":"given"},
    {"id":"yb","symbol":"lower bound on y","value":1,"provenance":"given"},
    {"id":"lc","symbol":"lower bound on x+2y","value":6,"provenance":"given"},
    {"id":"uc","symbol":"upper bound on 2x+y","value":9,"provenance":"given"},
    {"id":"ax","symbol":"A_x","value":2,"provenance":"given"},
    {"id":"ay","symbol":"A_y","value":2,"provenance":"given"},
