    {"id":"by","symbol":"B_y","value":2,"provenance":"given"},
    {"id":"cx","symbol":"C_x","value":1,"provenance":"given"},
    {"id":"cy","symbol":"C_y","value":2.5,"provenance":"given"},
    {"id":"yt","symbol":"y at upper-left corner","value":7,"provenance":"derived"},
    {"id":"xr","symbol":"x at right corner","value":4,"provenance":"derived"},
    {"id":"z1","symbol":"Z at (1,5/2)","value":9.5,"provenance":"derived"},
    {"id":"z2","symbol":"Z at (1,7)","value":23,"provenance":"derived"},
    {"id":"z3","symbol":"Z at (4,1)","value":11,"provenance":"derived"},
    {"id":"zm","symbol":"minimum Z","value":9.5,"provenance":"derived"}
  ],
  "entities": [
    {"id":"feasible","kind":"linear_region","role":"exact feasible region, objective, and stated-point classification"}
  ],
  "constructions": [
    {
      "id":"kFeasible",
      "operator":"linear_feasible_region",
      "inputs":{
        "variables":["x","y"],
        "constraints":["x>=1","y>=1","x+2y>=6","2x+y<=9"],
        "objective":{"expression":"2x+3y","sense":"min"}
      },
      "outputs":["feasible"]
    }
  ],
  "relations":[],
  "assertions":[],
  "annotations":[],
  "requiredEntityIds":["feasible"],
  "revealGroups":[
    {
      "id":"setup",
      "entityIds":["feasible"],
      "dependsOn":[],
      "narrationCue":"Graph the four stated inequalities over real pairs before evaluating the objective."
    }
  ],
  "teachingTimeline":[
    {"id":"showSetup","revealGroupId":"setup","targetIds":["feasible"],"narrationCue":"Show the exact feasible region."},
    {"id":"evaluate","targetIds":["feasible"],"narrationCue":"Then calculate each corner’s coordinates and Z value, mark the complete minimum set, and classify A, B, and C against the stated inequalities."}
  ]
}

